CREATE TABLE IF NOT EXISTS supplier_offers (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, source_key VARCHAR(100) NOT NULL, product_id VARCHAR(80) NOT NULL, supplier_name VARCHAR(160) NOT NULL, product_name VARCHAR(255) NOT NULL, billing_type VARCHAR(30) NOT NULL, binding_period VARCHAR(100) NULL, energy_price_dkk_kwh_ex_vat DECIMAL(12,6) NOT NULL, subscription_dkk_month_ex_vat DECIMAL(12,2) NOT NULL, annual_supplier_cost_dkk_inc_vat DECIMAL(14,2) NOT NULL, annual_saving_dkk_inc_vat DECIMAL(14,2) NOT NULL, maximum_consumption_kwh INT NULL, valid_from DATE NULL, valid_to DATE NULL, source_updated_at DATE NULL, source_url VARCHAR(500) NOT NULL, caveats_json JSON NOT NULL, fetched_at DATETIME(6) NOT NULL, UNIQUE KEY uq_supplier_offer(source_key,product_id), INDEX idx_supplier_saving(annual_saving_dkk_inc_vat));
CREATE TABLE IF NOT EXISTS supplier_watch_runs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, source_key VARCHAR(100) NOT NULL, fetched_at DATETIME(6) NOT NULL, status VARCHAR(30) NOT NULL, offer_count INT NOT NULL, source_hash CHAR(64) NULL, details_json JSON NOT NULL, INDEX idx_supplier_run_time(fetched_at));
